const item = $input.first().json;
const b = item.body ?? {};
// Campos obrigatórios por tipo. Faltou algum: o evento não segue - vira tarefa, não mensagem vazia.
const obrig = {
  'loja.criada': ['slug','nome','url'],
  'loja.provisionada': ['slug','nome','url','passos'],
  'loja.provisionamento-falhou': ['slug','nome','url','passos'],
  'loja.ativada': ['slug','nome','url'],
  'loja.identidade-atualizada': ['slug','nome','url'],
  'pedido.criado': ['slug','referencia','totalCentavos','meioPagamento','clienteNome','clienteTelefone','lojaNome'],
  'pedido.pago': ['slug','referencia','numero','totalCentavos','clienteNome','clienteEmail','itensTexto','lojaNome','lojaUrl'],
  'pedido.recusado': ['slug','referencia','clienteNome','clienteTelefone','lojaNome','lojaUrl'],
  'lojista.recuperar-senha': ['slug','nome','email','link'],
  'loja.suspensa': ['slug','nome','emailContato'],
  'loja.reativada': ['slug','nome','emailContato'],
  'loja.mensalidade-paga': ['slug','nome','centavos','emailContato'],
  'loja.mensalidade-recusada': ['slug','nome','tentativas','emailContato'],
  'carrinho.abandonado': ['slug','referencia','clienteNome','clienteEmail','itensTexto','totalCentavos','linkCarrinho','lojaNome'],
  'avaliacao.recebida': ['slug','nome','produtoNome','nota','emailContato'],
  'pedido.enviado': ['slug','referencia','numero','clienteNome','clienteEmail','transportadora','linkPedido','lojaNome'],
  'loja.voltou-ao-estoque': ['slug','nome','url','destinatario','produtoNome','precoCentavos'],
  'loja.relatorio-semanal': ['slug','nome','emailContato','periodo'],
  'pedido.em-separacao': ['slug','referencia','numero','clienteNome','clienteEmail','linkPedido','lojaNome'],
  'pedido.entregue': ['slug','referencia','numero','clienteNome','clienteEmail','linkPedido','lojaNome'],
  'pedido.cancelado': ['slug','referencia','numero','clienteNome','clienteEmail','linkPedido','lojaNome'],
};
const erros = [];
if (!b.eventId) erros.push('eventId ausente');
if (Number(b.versao ?? 1) !== 1) erros.push('versao ' + b.versao + ' desconhecida');
if (!b.tipo || !b.slug) erros.push('tipo/slug ausentes');
// Tipo que o fluxo não conhece não é inválido: passa, cai no fallback do switch e é encerrado como IGNORADO.
for (const c of (obrig[b.tipo] ?? [])) { const v = b[c]; if (v === undefined || v === null || v === '') erros.push(c + ' obrigatório'); }
return [{ json: { ...item, contratoValido: erros.length === 0, contratoErros: erros } }];

